package com.hbm.blocks.machine.rbmk;
import com.hbm.api.fluidmk2.IFluidConnectorBlockMK2; import com.hbm.tileentity.ModRBMKBlockEntities; import com.hbm.tileentity.machine.rbmk.BlockEntityRBMKOutlet; import net.minecraft.core.BlockPos; import net.minecraft.world.level.BlockGetter; import net.minecraft.world.level.Level; import net.minecraft.world.level.block.Block; import net.minecraft.world.level.block.EntityBlock; import net.minecraft.world.level.block.entity.BlockEntity; import net.minecraft.world.level.block.entity.BlockEntityTicker; import net.minecraft.world.level.block.entity.BlockEntityType; import net.minecraft.world.level.block.state.BlockState; import org.jspecify.annotations.Nullable;
/** Single-block ReaSim steam endpoint: source behavior intentionally exposes all six pipe faces. */
public class RBMKOutlet extends Block implements IFluidConnectorBlockMK2, EntityBlock { public RBMKOutlet(Properties properties) { super(properties); } @Override public @Nullable BlockEntity newBlockEntity(BlockPos pos, BlockState state) { return new BlockEntityRBMKOutlet(pos, state); } @Override public boolean canConnect(com.hbm.inventory.fluid.FluidType type, BlockGetter world, int x, int y, int z, com.hbm.lib.ForgeDirection dir) { return dir != com.hbm.lib.ForgeDirection.UNKNOWN && world.getBlockEntity(new BlockPos(x, y, z)) instanceof BlockEntityRBMKOutlet; } @Override public <T extends BlockEntity> @Nullable BlockEntityTicker<T> getTicker(Level level, BlockState state, BlockEntityType<T> type) { return RBMKTickers.ticker(level, type, ModRBMKBlockEntities.RBMK_OUTLET.get()); } }
